result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/merge_subs.py", "content": "#!/usr/bin/env python3
"""Bilingual SRT subtitle merger.

Merges two SRT tracks of the same video (original language + translation)
into a single track. Each output cue shows the original line(s) on top and
the translated line(s) below.

Pairing rule (IoU-style): cues a and b are paired when
    overlap_ms / min(dur_a, dur_b) >= 0.5
Chains merge transitively (e.g. one original cue split into two translation
cues forms a single output cue). Unpaired cues pass through alone, tagged
with '[untranslated]' or '[no source]' as the missing side. Output cue
timing spans the union of the paired cues' ranges.
"""

from __future__ import annotations

import argparse
import re
import sys
from dataclasses import dataclass, field

MIN_OVERLAP_RATIO = 0.5
UNTRANSLATED_TAG = "[untranslated]"
NO_SOURCE_TAG = "[no source]"

_TIME_RE = re.compile(
    r"(\d{1,2}):(\d{2}):(\d{2})[,.](\d{1,3})\s*-->\s*"
    r"(\d{1,2}):(\d{2}):(\d{2})[,.](\d{1,3})"
)


@dataclass
class Cue:
    index: int
    start: int  # ms
    end: int    # ms
    lines: list[str] = field(default_factory=list)

    @property
    def duration(self) -> int:
        return self.end - self.start


def ts_to_ms(h: str, m: str, s: str, ms: str) -> int:
    return ((int(h) * 60 + int(m)) * 60 + int(s)) * 1000 + int(ms.ljust(3, "0")[:3])


def ms_to_ts(ms: int) -> str:
    h, rem = divmod(ms, 3_600_000)
    m, rem = divmod(rem, 60_000)
    s, milli = divmod(rem, 1000)
    return f"{h:02d}:{m:02d}:{s:02d},{milli:03d}"


def parse_srt(text: str) -> list[Cue]:
    """Parse an SRT string into a list of Cues."""
    text = text.replace("\r\n", "\n").replace("\ufeff", "").strip()
    if not text:
        return []
    cues: list[Cue] = []
    blocks = re.split(r"\n\s*\n", text)
    for block in blocks:
        rows = [r for r in block.split("\n") if r.strip()]
        if not rows:
            continue
        time_idx = next(
            (i for i, r in enumerate(rows) if "-->" in r), None
        )
        if time_idx is None:
            continue
        m = _TIME_RE.search(rows[time_idx])
        if not m:
            continue
        start = ts_to_ms(*m.group(1, 2, 3, 4))
        end = ts_to_ms(*m.group(5, 6, 7, 8))
        # Index line: use it when present directly above the timing line.
        index = -1
        if time_idx > 0 and rows[time_idx - 1].strip().isdigit():
            index = int(rows[time_idx - 1].strip())
        lines = [r.strip() for r in rows[time_idx + 1:] if r.strip()]
        cues.append(Cue(index=index, start=start, end=end, lines=lines))
    return cues


def overlap(a_start: int, a_end: int, b_start: int, b_end: int) -> int:
    return max(0, min(a_end, b_end) - max(a_start, b_start))


def pairs_with(a: Cue, b: Cue) -> bool:
    ov = overlap(a.start, a.end, b.start, b.end)
    if ov == 0:
        return False
    return ov / min(a.duration, b.duration) >= MIN_OVERLAP_RATIO


class UnionFind:
    def __init__(self, n: int) -> None:
        self.parent = list(range(n))

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.parent[rb] = ra


def merge_tracks(original: list[Cue], translated: list[Cue]) -> list[Cue]:
    """Merge original + translated cue lists into one bilingual cue list."""
    all_cues = list(original) + list(translated)
    n_src = len(original)
    uf = UnionFind(len(all_cues))

    # Build pairing graph between the two tracks; chains merge transitively.
    for i, a in enumerate(original):
        for j in range(n_src, len(all_cues)):
            b = all_cues[j]
            if pairs_with(a, b):
                uf.union(i, j)

    groups: dict[int, list[int]] = {}
    for k in range(len(all_cues)):
        groups.setdefault(uf.find(k), []).append(k)

    merged: list[Cue] = []
    for members in groups.values():
        src = sorted((all_cues[k] for k in members if k < n_src), key=lambda c: c.start)
        dst = sorted((all_cues[k] for k in members if k >= n_src), key=lambda c: c.start)
        start = min(c.start for c in members and src + dst)
        end = max(c.end for c in src + dst)
        orig_lines = [line for c in src for line in c.lines]
        trans_lines = [line for c in dst for line in c.lines]
        top_lines = orig_lines if orig_lines else [NO_SOURCE_TAG]
        bottom_lines = trans_lines if trans_lines else [UNTRANSLATED_TAG]
        merged.append(
            Cue(index=-1, start=start, end=end, lines=top_lines + bottom_lines)
        )

    merged.sort(key=lambda c: (c.start, c.end))
    for i, cue in enumerate(merged, start=1):
        cue.index = i
    return merged


def format_srt(cues: list[Cue]) -> str:
    out: list[str] = []
    for cue in cues:
        out.append(str(cue.index))
        out.append(f"{ms_to_ts(cue.start)} --> {ms_to_ts(cue.end)}")
        out.extend(cue.lines)
        out.append("")
    return "\n".join(out)


def merge_srt_text(orig_text: str, trans_text: str) -> str:
    return format_srt(merge_tracks(parse_srt(orig_text), parse_srt(trans_text)))


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Merge two SRT tracks into one bilingual track.")
    ap.add_argument("original", help="SRT file in the original language")
    ap.add_argument("translation", help="SRT file with the translated track")
    ap.add_argument("-o", "--output", default="-", help="output path ('-' for stdout)")
    args = ap.parse_args(argv)

    with open(args.original, encoding="utf-8-sig") as f:
        orig_text = f.read()
    with open(args.translation, encoding="utf-8-sig") as f:
        trans_text = f.read()

    result = merge_srt_text(orig_text, trans_text)
    if args.output == "-":
        sys.stdout.write(result)
    else:
        with open(args.output, "w", encoding="utf-8") as f:
            f.write(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
